import { use } from 'react';
import { OverlayTriggerStateContext } from 'react-aria-components/Dialog';
import { PopoverContext } from 'react-aria-components/Popover';
import { useSlottedContext } from 'react-aria-components/slots';
import { useOverlayExitHold, resolveOverlayOpen } from './use-overlay-exit-hold.js';

/** Follow the same local and slotted animation options as React Aria's Popover. */
const usePopoverExitHold = (props, options) => {
  const context = useSlottedContext(PopoverContext, props.slot);
  const state = use(OverlayTriggerStateContext);
  const shouldSkipAnimation = props.shouldSkipAnimation ?? context?.shouldSkipAnimation;
  return useOverlayExitHold(resolveOverlayOpen(props.isOpen ?? context?.isOpen, props.defaultOpen ?? context?.defaultOpen, state), {
    ...options,
    enabled: !shouldSkipAnimation
  });
};

export { usePopoverExitHold };
